import { defineConfig } from 'vite';

export default defineConfig({
  test: {
    environment: 'jsdom',
    globals: true,
    setupFiles: []
  }
});

import './styles/main.css';
import { createApp } from './app.js';

const appRoot = document.querySelector('#app');

if (!appRoot) {
  throw new Error('App root element not found');
}

createApp(appRoot);

import { EventBus } from './services/EventBus.js';
import { StorageService } from './services/StorageService.js';
import { ScoreboardService } from './services/ScoreboardService.js';
import { MoveHistoryService } from './services/MoveHistoryService.js';
import { BlitzTimerService } from './services/BlitzTimerService.js';
import { CpuPlayerService } from './services/CpuPlayerService.js';
import { GameEngine } from './services/GameEngine.js';
import { DEFAULT_BLITZ_CONFIG, DEFAULT_GAME_MODE, EVENT_NAMES, SYMBOLS } from './utils/constants.js';
import { formatCellPosition } from './utils/helpers.js';

function renderTemplate(state) {
  const winnerText = state.winner ? `${state.winner} wins!` : state.outcome === 'draw' ? 'Match ended in a draw.' : 'Game in progress.';
  const blitzLabel = state.blitzEnabled ? `Blitz on (${state.blitzDurationSeconds}s)` : 'Blitz off';
  const timerMarkup = state.blitzEnabled
    ? `<section class="card timer-card" aria-label="Blitz countdown timer">
        <div class="card-header">
          <h2 class="card-title">Blitz Timer</h2>
          <span class="badge ${state.timerExpired ? 'badge-error' : state.remainingSeconds <= 3 ? 'badge-warning' : 'badge-neutral'}" aria-label="Time remaining">${state.remainingSeconds}s</span>
        </div>
        <p class="muted">${state.timerMessage}</p>
      </section>`
    : '';

  const movesMarkup = state.moves.length
    ? state.moves.map((move) => `
      <li class="history-item ${move.playerType === 'cpu' ? 'history-item-cpu' : 'history-item-player'}" aria-label="Move history entry">
        <div class="history-index">#${move.moveNumber}</div>
        <div class="history-content">
          <strong>${move.player}</strong>
          <span>${move.symbol} · ${formatCellPosition(move.cellIndex)}</span>
        </div>
        <div class="history-meta">${new Date(move.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div>
      </li>`).join('')
    : '<li class="empty-state">No moves yet. Start a match to see the log.</li>';

  const boardCells = state.board.map((cell, index) => {
    const winning = state.winningCells.includes(index);
    const label = cell ? `Cell ${index + 1}, ${cell}` : `Cell ${index + 1}, empty`;
    return `<button class="board-cell ${winning ? 'board-cell-winning' : ''}" data-cell-index="${index}" aria-label="${label}" ${state.phase === 'match-ended' || cell ? '' : ''}>${cell || ''}</button>`;
  }).join('');

  return `
    <main class="page" aria-label="Game session page">
      <header class="hero">
        <div>
          <h1>Tic-Tac-Toe Advanced Features</h1>
          <p class="muted">Local PvP and Vs CPU play with persistent scoreboard, move history, and optional blitz mode.</p>
        </div>
        <div class="hero-status">
          <span class="badge badge-neutral">${state.gameMode === 'cpu' ? 'Vs CPU' : 'Local PvP'}</span>
          <span class="badge ${state.blitzEnabled ? 'badge-warning' : 'badge-neutral'}">${blitzLabel}</span>
        </div>
      </header>

      <section class="layout">
        <section class="card controls-card" aria-label="Game controls">
          <div class="card-header">
            <h2 class="card-title">Game Controls</h2>
            <p class="muted">${winnerText}</p>
          </div>
          <div class="controls-grid">
            <label class="field">
              <span>Game mode</span>
              <select id="gameMode" aria-label="Game mode selector">
                <option value="pvp" ${state.gameMode === 'pvp' ? 'selected' : ''}>Local PvP</option>
                <option value="cpu" ${state.gameMode === 'cpu' ? 'selected' : ''}>Vs CPU</option>
              </select>
            </label>
            <label class="toggle">
              <input id="blitzEnabled" type="checkbox" ${state.blitzEnabled ? 'checked' : ''} aria-label="Toggle blitz mode" />
              <span>Blitz mode</span>
            </label>
            <label class="field">
              <span>Blitz duration</span>
              <input id="blitzDuration" type="number" min="3" max="60" value="${state.blitzDurationSeconds}" aria-label="Blitz duration in seconds" />
            </label>
            <button id="newMatch" class="btn btn-primary" type="button" aria-label="Start new match">New match</button>
            <button id="resetScores" class="btn btn-danger" type="button" aria-label="Reset session scores">Reset scores</button>
          </div>
        </section>

        ${timerMarkup}

        <section class="card board-card" aria-label="Game board">
          <div class="card-header">
            <h2 class="card-title">Board</h2>
            <span class="muted">Turn: ${state.currentPlayer}</span>
          </div>
          <div class="board" role="grid" aria-label="Tic-tac-toe board">
            ${boardCells}
          </div>
        </section>

        <section class="card scoreboard-card" aria-label="Session scoreboard">
          <div class="card-header">
            <h2 class="card-title">Session Scoreboard</h2>
            <button id="scoreboardResetTop" class="btn btn-ghost" type="button" aria-label="Reset session scores">Reset</button>
          </div>
          <div class="scoreboard-grid">
            <div class="score-item"><span>Wins</span><strong>${state.scoreboard.player1Wins}</strong></div>
            <div class="score-item"><span>Losses</span><strong>${state.scoreboard.player1Losses}</strong></div>
            <div class="score-item"><span>Draws</span><strong>${state.scoreboard.draws}</strong></div>
          </div>
          <p class="muted">Last updated: ${state.scoreboard.lastUpdated ? new Date(state.scoreboard.lastUpdated).toLocaleString() : 'Never'}</p>
        </section>

        <section class="card history-card" aria-label="Move history log">
          <div class="card-header">
            <h2 class="card-title">Move History</h2>
            <span class="muted">${state.moves.length} moves</span>
          </div>
          <ul class="history-list">
            ${movesMarkup}
          </ul>
        </section>
      </section>
    </main>
  `;
}

function buildInitialState(services) {
  const scoreboard = services.scoreboardService.getState();
  const blitzConfig = services.blitzTimerService.getConfig();
  return {
    phase: 'loading',
    board: Array(9).fill(''),
    currentPlayer: 'Player 1',
    gameMode: scoreboard.gameMode || DEFAULT_GAME_MODE,
    blitzEnabled: blitzConfig.enabled,
    blitzDurationSeconds: blitzConfig.durationSeconds,
    remainingSeconds: blitzConfig.durationSeconds,
    timerExpired: false,
    timerMessage: 'Blitz mode is disabled.',
    scoreboard,
    moves: services.moveHistoryService.getMoves(),
    winner: null,
    outcome: null,
    winningCells: []
  };
}

export function createApp(rootElement) {
  const eventBus = new EventBus();
  const storageService = new StorageService(window.localStorage);
  const cpuPlayerService = new CpuPlayerService(eventBus);
  const moveHistoryService = new MoveHistoryService(eventBus);
  const blitzTimerService = new BlitzTimerService(eventBus, { ...DEFAULT_BLITZ_CONFIG });
  const scoreboardService = new ScoreboardService(storageService, eventBus);
  const gameEngine = new GameEngine(eventBus, cpuPlayerService, moveHistoryService, blitzTimerService);

  const services = {
    scoreboardService,
    moveHistoryService,
    blitzTimerService,
    gameEngine
  };

  const state = buildInitialState(services);
  state.phase = 'ready';

  function syncState() {
    const engineState = gameEngine.getState();
    state.board = engineState.board;
    state.currentPlayer = engineState.currentPlayer;
    state.gameMode = engineState.gameMode;
    state.blitzEnabled = engineState.blitzEnabled;
    state.blitzDurationSeconds = engineState.blitzDurationSeconds;
    state.remainingSeconds = engineState.remainingSeconds;
    state.timerExpired = engineState.timerExpired;
    state.timerMessage = engineState.timerMessage;
    state.winner = engineState.winner;
    state.outcome = engineState.outcome;
    state.winningCells = engineState.winningCells;
    state.moves = moveHistoryService.getMoves();
    state.scoreboard = scoreboardService.getState();
    state.phase = engineState.outcome ? 'match-ended' : 'playing';
  }

  function render() {
    rootElement.innerHTML = renderTemplate(state);
    const boardButtons = rootElement.querySelectorAll('[data-cell-index]');
    boardButtons.forEach((button) => {
      button.addEventListener('click', () => {
        const index = Number(button.getAttribute('data-cell-index'));
        gameEngine.playMove(index);
        syncState();
        render();
      });
    });

    const newMatch = rootElement.querySelector('#newMatch');
    const resetScores = rootElement.querySelector('#resetScores');
    const scoreboardResetTop = rootElement.querySelector('#scoreboardResetTop');
    const gameMode = rootElement.querySelector('#gameMode');
    const blitzEnabled = rootElement.querySelector('#blitzEnabled');
    const blitzDuration = rootElement.querySelector('#blitzDuration');

    newMatch?.addEventListener('click', () => {
      gameEngine.resetBoard();
      syncState();
      render();
    });

    const resetHandler = () => {
      scoreboardService.reset();
      syncState();
      render();
    };

    resetScores?.addEventListener('click', resetHandler);
    scoreboardResetTop?.addEventListener('click', resetHandler);

    gameMode?.addEventListener('change', (event) => {
      const target = event.target;
      if (target instanceof HTMLSelectElement) {
        gameEngine.updateSettings({ gameMode: target.value });
        syncState();
        render();
      }
    });

    blitzEnabled?.addEventListener('change', (event) => {
      const target = event.target;
      if (target instanceof HTMLInputElement) {
        gameEngine.updateSettings({ blitzEnabled: target.checked });
        syncState();
        render();
      }
    });

    blitzDuration?.addEventListener('change', (event) => {
      const target = event.target;
      if (target instanceof HTMLInputElement) {
        gameEngine.updateSettings({ blitzDurationSeconds: Number(target.value) });
        syncState();
        render();
      }
    });
  }

  const rerender = () => {
    syncState();
    render();
  };

  eventBus.subscribe(EVENT_NAMES.STATE_CHANGED, rerender);
  eventBus.subscribe(EVENT_NAMES.MATCH_CONCLUDED, rerender);
  eventBus.subscribe(EVENT_NAMES.BOARD_RESET, rerender);
  eventBus.subscribe(EVENT_NAMES.GAME_MODE_CHANGED, rerender);
  eventBus.subscribe(EVENT_NAMES.TIMER_TICK, rerender);

  gameEngine.initialize();
  syncState();
  render();

  return {
    destroy() {
      eventBus.clear();
    }
  };
}

export const EVENT_NAMES = {
  MOVE_MADE: 'MOVE_MADE',
  MATCH_CONCLUDED: 'MATCH_CONCLUDED',
  TURN_FORFEITED: 'TURN_FORFEITED',
  TIMER_TICK: 'TIMER_TICK',
  BOARD_RESET: 'BOARD_RESET',
  GAME_MODE_CHANGED: 'GAME_MODE_CHANGED',
  STATE_CHANGED: 'STATE_CHANGED'
};

export const STORAGE_KEYS = {
  SCOREBOARD: 'ttt_scoreboard',
  MOVE_HISTORY: 'ttt_move_history',
  BLITZ_CONFIG: 'ttt_blitz_config'
};

export const DEFAULT_GAME_MODE = 'pvp';
export const PLAYER_ONE = 'Player 1';
export const PLAYER_TWO = 'Player 2';
export const CPU_PLAYER = 'CPU';
export const SYMBOLS = { X: 'X', O: 'O' };
export const DEFAULT_BLITZ_CONFIG = { enabled: false, durationSeconds: 10 };
export const DEFAULT_SCOREBOARD = {
  player1Wins: 0,
  player1Losses: 0,
  draws: 0,
  gameMode: DEFAULT_GAME_MODE,
  lastUpdated: new Date().toISOString()
};

export function formatCellPosition(index) {
  const row = Math.floor(index / 3);
  const col = index % 3;
  return `${String.fromCharCode(65 + row)}${col + 1}`;
}

export function getWinningLines() {
  return [
    [0, 1, 2],
    [3, 4, 5],
    [6, 7, 8],
    [0, 3, 6],
    [1, 4, 7],
    [2, 5, 8],
    [0, 4, 8],
    [2, 4, 6]
  ];
}

export function isValidCellIndex(index) {
  return Number.isInteger(index) && index >= 0 && index < 9;
}

export class EventBus {
  constructor() {
    this.listeners = new Map();
  }

  subscribe(eventName, callback) {
    if (!this.listeners.has(eventName)) {
      this.listeners.set(eventName, new Set());
    }
    this.listeners.get(eventName).add(callback);
    return () => this.unsubscribe(eventName, callback);
  }

  unsubscribe(eventName, callback) {
    const set = this.listeners.get(eventName);
    if (set) set.delete(callback);
  }

  emit(eventName, payload) {
    const set = this.listeners.get(eventName);
    if (!set) return;
    for (const callback of [...set]) {
      callback(payload);
    }
  }

  clear() {
    this.listeners.clear();
  }
}

export class StorageService {
  constructor(storage) {
    this.storage = storage;
  }

  get(key, fallbackValue = null) {
    try {
      const raw = this.storage.getItem(key);
      if (raw === null) return fallbackValue;
      return JSON.parse(raw);
    } catch {
      return fallbackValue;
    }
  }

  set(key, value) {
    this.storage.setItem(key, JSON.stringify(value));
  }

  remove(key) {
    this.storage.removeItem(key);
  }
}

import { DEFAULT_SCOREBOARD, EVENT_NAMES, STORAGE_KEYS } from '../utils/constants.js';

export class ScoreboardService {
  constructor(storageService, eventBus) {
    this.storageService = storageService;
    this.eventBus = eventBus;
    this.state = this.load();
    this.eventBus.subscribe(EVENT_NAMES.MATCH_CONCLUDED, (payload) => this.handleMatchConcluded(payload));
  }

  load() {
    const stored = this.storageService.get(STORAGE_KEYS.SCOREBOARD, null);
    return stored && typeof stored === 'object'
      ? { ...DEFAULT_SCOREBOARD, ...stored }
      : { ...DEFAULT_SCOREBOARD };
  }

  save() {
    this.state.lastUpdated = new Date().toISOString();
    this.storageService.set(STORAGE_KEYS.SCOREBOARD, this.state);
  }

  handleMatchConcluded(payload) {
    if (!payload) return;
    if (payload.outcome === 'draw') {
      this.state.draws += 1;
    } else if (payload.winner === 'Player 1') {
      this.state.player1Wins += 1;
    } else if (payload.winner) {
      this.state.player1Losses += 1;
    }
    if (payload.gameMode) this.state.gameMode = payload.gameMode;
    this.save();
    this.eventBus.emit(EVENT_NAMES.STATE_CHANGED, this.state);
  }

  getState() {
    return { ...this.state };
  }

  reset() {
    this.state = { ...DEFAULT_SCOREBOARD };
    this.storageService.remove(STORAGE_KEYS.SCOREBOARD);
    this.save();
    this.eventBus.emit(EVENT_NAMES.STATE_CHANGED, this.state);
  }
}

import { EVENT_NAMES } from '../utils/constants.js';

export class MoveHistoryService {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.moves = [];
    this.eventBus.subscribe(EVENT_NAMES.MOVE_MADE, (move) => this.addMove(move));
    this.eventBus.subscribe(EVENT_NAMES.BOARD_RESET, () => this.clear());
  }

  addMove(move) {
    this.moves = [...this.moves, move];
    this.eventBus.emit(EVENT_NAMES.STATE_CHANGED, this.getMoves());
  }

  clear() {
    this.moves = [];
    this.eventBus.emit(EVENT_NAMES.STATE_CHANGED, this.getMoves());
  }

  getMoves() {
    return [...this.moves];
  }
}

import { DEFAULT_BLITZ_CONFIG, EVENT_NAMES, STORAGE_KEYS } from '../utils/constants.js';

export class BlitzTimerService {
  constructor(eventBus, initialConfig = DEFAULT_BLITZ_CONFIG) {
    this.eventBus = eventBus;
    this.config = { ...DEFAULT_BLITZ_CONFIG, ...initialConfig };
    this.remainingSeconds = this.config.durationSeconds;
    this.timerId = null;
    this.eventBus.subscribe(EVENT_NAMES.GAME_MODE_CHANGED, (payload) => this.updateConfig(payload));
    this.eventBus.subscribe(EVENT_NAMES.BOARD_RESET, () => this.cancel());
    this.eventBus.subscribe(EVENT_NAMES.MATCH_CONCLUDED, () => this.cancel());
    this.eventBus.subscribe(EVENT_NAMES.TURN_FORFEITED, () => this.cancel());
  }

  getConfig() {
    return { ...this.config };
  }

  updateConfig(payload) {
    this.config = {
      enabled: typeof payload?.blitzEnabled === 'boolean' ? payload.blitzEnabled : this.config.enabled,
      durationSeconds: Number.isFinite(payload?.blitzDurationSeconds) ? payload.blitzDurationSeconds : this.config.durationSeconds
    };
    this.remainingSeconds = this.config.durationSeconds;
  }

  start() {
    this.cancel();
    if (!this.config.enabled) return;
    this.remainingSeconds = this.config.durationSeconds;
    this.eventBus.emit(EVENT_NAMES.TIMER_TICK, { remainingSeconds: this.remainingSeconds });
    this.timerId = window.setInterval(() => {
      this.remainingSeconds -= 1;
      this.eventBus.emit(EVENT_NAMES.TIMER_TICK, { remainingSeconds: this.remainingSeconds });
      if (this.remainingSeconds <= 0) {
        this.cancel();
        this.eventBus.emit(EVENT_NAMES.TURN_FORFEITED, { forfeitedPlayer: null, gameMode: null });
      }
    }, 1000);
  }

  reset() {
    this.start();
  }

  cancel() {
    if (this.timerId !== null) {
      window.clearInterval(this.timerId);
      this.timerId = null;
    }
  }
}

export class CpuPlayerService {
  constructor(eventBus) {
    this.eventBus = eventBus;
  }

  chooseMove(board) {
    const available = board.map((cell, index) => (cell ? null : index)).filter((value) => value !== null);
    if (available.length === 0) return null;
    const preferred = [4, 0, 2, 6, 8, 1, 3, 5, 7].find((index) => available.includes(index));
    return preferred ?? available[0];
  }
}

import { CPU_PLAYER, DEFAULT_GAME_MODE, EVENT_NAMES, PLAYER_ONE, PLAYER_TWO, SYMBOLS } from '../utils/constants.js';
import { getWinningLines, isValidCellIndex } from '../utils/helpers.js';

export class GameEngine {
  constructor(eventBus, cpuPlayerService, moveHistoryService, blitzTimerService) {
    this.eventBus = eventBus;
    this.cpuPlayerService = cpuPlayerService;
    this.moveHistoryService = moveHistoryService;
    this.blitzTimerService = blitzTimerService;
    this.state = this.createInitialState();
    this.eventBus.subscribe(EVENT_NAMES.TURN_FORFEITED, () => this.handleForfeit());
  }

  createInitialState() {
    return {
      board: Array(9).fill(''),
      currentPlayer: PLAYER_ONE,
      currentSymbol: SYMBOLS.X,
      gameMode: DEFAULT_GAME_MODE,
      blitzEnabled: false,
      blitzDurationSeconds: 10,
      remainingSeconds: 10,
      timerExpired: false,
      timerMessage: 'Blitz mode is disabled.',
      winner: null,
      outcome: null,
      winningCells: []
    };
  }

  initialize() {
    this.resetBoard();
  }

  getState() {
    return { ...this.state, board: [...this.state.board], winningCells: [...this.state.winningCells] };
  }

  updateSettings(settings) {
    this.state.gameMode = settings.gameMode || this.state.gameMode;
    this.state.blitzEnabled = typeof settings.blitzEnabled === 'boolean' ? settings.blitzEnabled : this.state.blitzEnabled;
    this.state.blitzDurationSeconds = Number.isFinite(settings.blitzDurationSeconds) ? settings.blitzDurationSeconds : this.state.blitzDurationSeconds;
    this.state.remainingSeconds = this.state.blitzDurationSeconds;
    this.state.timerMessage = this.state.blitzEnabled ? `${this.state.remainingSeconds}s remaining` : 'Blitz mode is disabled.';
    this.eventBus.emit(EVENT_NAMES.GAME_MODE_CHANGED, {
      gameMode: this.state.gameMode,
      blitzEnabled: this.state.blitzEnabled,
      blitzDurationSeconds: this.state.blitzDurationSeconds
    });
    this.eventBus.emit(EVENT_NAMES.STATE_CHANGED, this.getState());
  }

  resetBoard() {
    this.state = { ...this.createInitialState(), gameMode: this.state.gameMode, blitzEnabled: this.state.blitzEnabled, blitzDurationSeconds: this.state.blitzDurationSeconds };
    this.eventBus.emit(EVENT_NAMES.BOARD_RESET, { gameMode: this.state.gameMode, blitzEnabled: this.state.blitzEnabled });
    if (this.state.blitzEnabled) this.blitzTimerService.start();
    this.eventBus.emit(EVENT_NAMES.STATE_CHANGED, this.getState());
  }

  playMove(index) {
    if (!isValidCellIndex(index) || this.state.board[index] || this.state.outcome) return false;
    this.state.board[index] = this.state.currentSymbol;
    const move = {
      moveNumber: this.moveHistoryService.getMoves().length + 1,
      player: this.state.currentPlayer,
      symbol: this.state.currentSymbol,
      cellIndex: index,
      timestamp: new Date().toISOString(),
      playerType: this.state.gameMode === 'cpu' && this.state.currentPlayer === PLAYER_TWO ? 'cpu' : 'player'
    };
    this.eventBus.emit(EVENT_NAMES.MOVE_MADE, move);
    const result = this.checkWinner();
    if (result) {
      this.state.outcome = result.outcome;
      this.state.winner = result.winner;
      this.state.winningCells = result.winningCells;
      this.eventBus.emit(EVENT_NAMES.MATCH_CONCLUDED, { outcome: result.outcome, winner: result.winner, gameMode: this.state.gameMode });
      return true;
    }
    if (this.state.board.every(Boolean)) {
      this.state.outcome = 'draw';
      this.state.winner = null;
      this.eventBus.emit(EVENT_NAMES.MATCH_CONCLUDED, { outcome: 'draw', winner: null, gameMode: this.state.gameMode });
      return true;
    }
    this.toggleTurn();
    if (this.state.gameMode === 'cpu' && this.state.currentPlayer === PLAYER_TWO) {
      const cpuMove = this.cpuPlayerService.chooseMove(this.state.board);
      if (cpuMove !== null) this.playMove(cpuMove);
    }
    if (this.state.blitzEnabled) this.blitzTimerService.reset();
    this.eventBus.emit(EVENT_NAMES.STATE_CHANGED, this.getState());
    return true;
  }

  toggleTurn() {
    this.state.currentPlayer = this.state.currentPlayer === PLAYER_ONE ? PLAYER_TWO : PLAYER_ONE;
    this.state.currentSymbol = this.state.currentSymbol === SYMBOLS.X ? SYMBOLS.O : SYMBOLS.X;
  }

  handleForfeit() {
    if (this.state.outcome) return;
    const winner = this.state.currentPlayer === PLAYER_ONE ? PLAYER_TWO : PLAYER_ONE;
    this.state.outcome = 'win';
    this.state.winner = winner;
    this.eventBus.emit(EVENT_NAMES.MATCH_CONCLUDED, { outcome: 'win', winner, gameMode: this.state.gameMode });
  }

  checkWinner() {
    for (const line of getWinningLines()) {
      const [a, b, c] = line;
      const symbol = this.state.board[a];
      if (symbol && symbol === this.state.board[b] && symbol === this.state.board[c]) {
        return { outcome: 'win', winner: symbol === SYMBOLS.X ? PLAYER_ONE : this.state.gameMode === 'cpu' && symbol === SYMBOLS.O ? CPU_PLAYER : PLAYER_TWO, winningCells: line };
      }
    }
    return null;
  }
}

import { describe, expect, it, beforeEach, vi } from 'vitest';
import { StorageService } from '../src/services/StorageService.js';

describe('StorageService', () => {
  let storage;

  beforeEach(() => {
    storage = {
      getItem: vi.fn(),
      setItem: vi.fn(),
      removeItem: vi.fn()
    };
  });

  it('returns fallback for missing values', () => {
    storage.getItem.mockReturnValue(null);
    const service = new StorageService(storage);
    expect(service.get('missing', { ok: true })).toEqual({ ok: true });
  });

  it('serializes and stores JSON values', () => {
    const service = new StorageService(storage);
    service.set('key', { value: 1 });
    expect(storage.setItem).toHaveBeenCalledWith('key', '{"value":1}');
  });
});
